from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build(tree):
    # LeetCode list -> linked nodes. Each popped parent takes the next two slots.
    if not tree or tree[0] is None:
        return None
    root = Node(tree[0])
    queue = deque([root])
    i = 1
    while queue and i < len(tree):
        node = queue.popleft()
        if i < len(tree) and tree[i] is not None:
            node.left = Node(tree[i])
            queue.append(node.left)
        i += 1
        if i < len(tree) and tree[i] is not None:
            node.right = Node(tree[i])
            queue.append(node.right)
        i += 1
    return root

def solution(tree, p, q):
    root = build(tree)
    parent = {root.val: None}       # value -> parent value; the root has none
    stack = [root]
    while p not in parent or q not in parent:
        node = stack.pop()
        for child in (node.left, node.right):
            if child is not None:
                parent[child.val] = node.val
                stack.append(child)
    ancestors = set()               # p and every node above it
    value = p
    while value is not None:
        ancestors.add(value)
        value = parent[value]
    value = q                       # climb from q to the first shared ancestor
    while value not in ancestors:
        value = parent[value]
    return value

