from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build(tree):
    # LeetCode list -> linked nodes. Each popped parent takes the next two slots.
    if not tree or tree[0] is None:
        return None
    root = Node(tree[0])
    queue = deque([root])
    i = 1
    while queue and i < len(tree):
        node = queue.popleft()
        if i < len(tree) and tree[i] is not None:
            node.left = Node(tree[i])
            queue.append(node.left)
        i += 1
        if i < len(tree) and tree[i] is not None:
            node.right = Node(tree[i])
            queue.append(node.right)
        i += 1
    return root

def subtree_values(node):
    values = set()
    stack = [node]
    while stack:
        cur = stack.pop()
        values.add(cur.val)
        for child in (cur.left, cur.right):
            if child is not None:
                stack.append(child)
    return values

def solution(tree, p, q):
    # Check every node's whole subtree; keep the deepest node that holds both.
    # O(n) per node, so O(n^2) on a deep tree.
    root = build(tree)
    best = None
    best_depth = -1
    stack = [(root, 0)]
    while stack:
        node, depth = stack.pop()
        values = subtree_values(node)
        if p in values and q in values and depth > best_depth:
            best = node.val
            best_depth = depth
        for child in (node.left, node.right):
            if child is not None:
                stack.append((child, depth + 1))
    return best
